"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3303],{9359(e){e.exports=JSON.parse('{"title":"useIsomorphicEffect\ub294 \uc5c6\ub2e4.","date":"2025-03-06","coverUrl":"/kudzu-based-bench/assets/notion/439023106ab534da.png","html":"<h2 data-notion-block-id=\\"1aae548d-8a8e-80c0-944f-e487245a446d\\" id=\\"1aae548d-8a8e-80c0-944f-e487245a446d\\"><code>useIsomorphicEffect</code>\ub294 \uc5c6\ub2e4.</h2><a href=\\"https://smoores.dev/post/no_such_thing_isomorphic_layout_effect/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://smoores.dev/post/no_such_thing_isomorphic_layout_effect/</a><p data-notion-block-id=\\"1aae548d-8a8e-80e6-a149-f7a45d063cd9\\">\ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c <code>useLayoutEffect</code>\uc640 <code>useEffect</code>\ub97c \uc870\ud569\ud574\uc11c <code>useIsomorphicEffect</code>\ub85c \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \uc885\uc885 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uacbd\uc6b0 <code>useEffect</code>\ub294 \uc544\ubb34 \uc5ed\ud560\uc744 \ud558\uc9c0 \uc54a\ub294 \uc0ac\uc2e4\uc744 \uac04\uacfc\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \uc9c0\uc801\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud56d\uc0c1 <code>useLayoutEffect</code>\uc0ac\uc6a9\uc774 \uacbd\uace0\uc5d0 \uadf8\uce58\ub294 \uc774\uc720\ub294, \uadf8\uc800 \uc8fc\uc758\ud558\ub77c\ub294 \uc774\uc57c\uae30\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-8001-a3a0-ffe5a5c207bd\\" id=\\"1aae548d-8a8e-8001-a3a0-ffe5a5c207bd\\">TypeScript \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \ub2e4\uc6b4\ud0c0\uc784 \uc5c6\uc774 \uc644\ub8cc\ud558\uae30</h2><a href=\\"https://benhowdle.im/migrating-js-to-ts-zero-downtime.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://benhowdle.im/migrating-js-to-ts-zero-downtime.html</a><p data-notion-block-id=\\"1aae548d-8a8e-8043-833f-f63957c940d9\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud55c \uc5ec\ub7ec <a href=\\"https://ones-to-watch.ethansup.net/news/post/a50a179e-3bb4-4959-83d9-4f5ed59bba5d#3a6644d1-aec5-404e-bbf8-87d511296f40\\">Migration \ubc29\uc2dd \uc18c\uac1c</a>\uc640 \uac19\uc774, \uc5ec\ub7ec \uc804\ub7b5 \uc911\uc5d0 \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\uac8c \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \ud0dd\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5ec\ub7ec \ub3c4\uad6c\uc640 \ud568\uaed8 \uc18c\uac1c\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ub098\uc911\uc5d0 \uc694\uad6c\uc0ac\ud56d\uc774 \ub2e4\uac00\uc624\uba74 \uc774 \ub3c4\uad6c \uc911\uc5d0 \uc120\ud0dd\ud558\ub294 \uac83\uc744 \uace0\ub824\ud558\ub294 \uac83\ub3c4 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1ade548d-8a8e-8025-ae69-c5f3503f9ec9\\" id=\\"1ade548d-8a8e-8025-ae69-c5f3503f9ec9\\">\uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c\uc758 HTTP/2\uc758 \uc758\ubbf8</h2><a href=\\"https://byroot.github.io/ruby/performance/2025/02/24/http2-past-the-load-balancer.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://byroot.github.io/ruby/performance/2025/02/24/http2-past-the-load-balancer.html</a><p data-notion-block-id=\\"1ade548d-8a8e-80ec-b9c4-f1688a068f9f\\">HTTP/2\uac00 \ub4f1\uc7a5\ud55c \ubc30\uacbd\uacfc \uc5b4\ub5a4 \uac83\uc744 \uac1c\uc120\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc65c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uc11c\ubc84\uc5d0\uc11c HTTP/2\uc758 \uc758\ubbf8\uac00 \ud1f4\uc0c9\ub418\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/150e548d-8a8e-80c3-9a65-d76db36a4789#152e548d-8a8e-80c6-97aa-c05c29dca568\\">\ube0c\ub77c\uc6b0\uc800\uc758 \ub85c\ub529 \ub9e4\ucee4\ub2c8\uc998</a> \ubc1c\ud45c\uc5d0\uc11c HTTP/2\ub97c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uc11c\ubc84\uc5d0\uc11c \uc81c\ub300\ub85c \ucc98\ub9ac\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc5d0 \ub300\ud55c \uc774\uc720\uac00 \ub420 \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80fd-9c2f-da6bb0629a60\\" id=\\"1aae548d-8a8e-80fd-9c2f-da6bb0629a60\\">React\uc5d0\uc11c \ud754\ud788 \uacaa\ub294 \uc131\ub2a5 \ubb38\uc81c \ud574\uacb0</h2><a href=\\"https://blog.sentry.io/react-js-performance-guide/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/react-js-performance-guide/</a><p data-notion-block-id=\\"1aae548d-8a8e-8062-9712-f6a21bec860a\\">Sentry\uc5d0\uc11c React \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uc77c\ubc18\uc801\uc73c\ub85c \uacaa\ub294 \uc131\ub2a5 \ubb38\uc81c\uc640 \ud574\uacb0\ud558\ub294 \ub2e4\uc591\ud55c \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80ad-a55b-ed6dfdd124d3\\" id=\\"1aae548d-8a8e-80ad-a55b-ed6dfdd124d3\\">\ubaa8\ubc14\uc77c \uc6f9 \uc11c\ube44\uc2a4\ub294 \ubcc4\ub85c \uc5c6\uc744\uae4c</h2><a href=\\"https://adactio.com/journal/21728\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://adactio.com/journal/21728</a><p data-notion-block-id=\\"1aae548d-8a8e-8003-a58c-db46bce8d53f\\">\ubaa8\ubc14\uc77c \uc6f9 \ub300\uc2e0 \ubaa8\ubc14\uc77c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \uad6c\ud604\ud558\ub294 \ubb38\ud654\ub54c\ubb38\uc5d0 \ubaa8\ubc14\uc77c \uc6f9\uc758 \uacbd\ud5d8\uc774 \ub9ce\uc774 \ub098\uc058\ub2e4\ub294 \uc0c8\ub85c\uc6b4 \uad00\uc810\uc758 \uae00\uc785\ub2c8\ub2e4. \ub531\ud788 \ud574\uacb0\ucc45\uc744 \uc81c\uc2dc\ud574\uc8fc\uc9c4 \uc54a\uc9c0\ub9cc, \ud604\uc7ac \ubaa8\ubc14\uc77c \uc6f9\uc740 \ub370\uc2a4\ud06c\ud0d1 \uc6f9\ub9cc\ud07c \uc9c0\uc6d0\uc744 \ub9ce\uc774 \ud558\uace0 \uc788\uc5b4 \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80c3-ab2d-fd5294b5688a\\" id=\\"1aae548d-8a8e-80c3-ab2d-fd5294b5688a\\"><code>cache()</code>\ub85c Server Components\uc758 waterfall \ubc29\uc9c0\ud558\uae30</h2><a href=\\"https://aurorascharff.no/posts/avoiding-server-component-waterfall-fetching-with-react-19-cache/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aurorascharff.no/posts/avoiding-server-component-waterfall-fetching-with-react-19-cache/</a><p data-notion-block-id=\\"1aae548d-8a8e-80e3-a8f8-c831d2919ac1\\">React 19\ub85c \ub4e4\uc5b4\uc624\uba74\uc11c <code>cache()</code>\ud568\uc218\ub85c React\uc5d0\uc11c \ub370\uc774\ud130 \uac12\uc744 \uce90\uc2dc\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. Server Components\uc758 waterfall\uc744 \uadfc\ubcf8\uc801\uc73c\ub85c \ud574\uacb0\ud560 \uc218\ub294 \uc5c6\uc9c0\ub9cc, \uce90\uc2f1\uc73c\ub85c \ubcf4\uc644\ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc774 \uae00\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 <code>cache()</code> \ud568\uc218\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uacfc \uc8fc\uc758\ud574\uc57c \ud558\ub294 \ubc95\uc744 \uc778\uc9c0\ud558\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-8049-b2e7-fc5dbc43458a\\" id=\\"1aae548d-8a8e-8049-b2e7-fc5dbc43458a\\">\ub300\uccb4 \ud14d\uc2a4\ud2b8 \uc0dd\uc131 \ube44\uad50 \uc2e4\ud5d8</h2><a href=\\"https://dri.es/comparing-local-llms-for-alt-text-generation\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dri.es/comparing-local-llms-for-alt-text-generation</a><p data-notion-block-id=\\"1aae548d-8a8e-805b-b8e4-e3f057d71c22\\">\uc5ec\ub7ec LLM\uc73c\ub85c \uc774\ubbf8\uc9c0\uc758 Alt text\ub97c \uc790\ub3d9\uc73c\ub85c \uc0dd\uc131\ud558\uace0 \uc798 \uc0dd\uc131\ud588\ub294\uc9c0 \ud14c\uc2a4\ud2b8\ud574\ubcf4\ub294 \uc7ac\ubc0c\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5ec\ub7ec LLM\uacfc \uadf8\ub97c \ubcf4\uc644\ud560\ub9cc\ud55c \ubc29\ubc95\uc744 \uc81c\uc2dc\ud558\uace0 \uc788\uc73c\ubbc0\ub85c \uac00\ubccd\uac8c \uc77d\uc5b4\ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80ba-84fd-da316a92f5a0\\" id=\\"1aae548d-8a8e-80ba-84fd-da316a92f5a0\\">Tanstack Router\uc5d0 \ub300\ud55c \uace0\ucc30</h2><a href=\\"https://gist.github.com/mitsuhiko/555b45f020a8d7e389516b51f6d03534\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gist.github.com/mitsuhiko/555b45f020a8d7e389516b51f6d03534</a><p data-notion-block-id=\\"1aae548d-8a8e-8034-85e6-e3223893db12\\">Tanstack Router\uc758 \uba54\ud0c0 \ud504\ub808\uc784\uc6cc\ud06c \uc811\uadfc\ubc95\uc5d0 \ub300\ud55c \uc8fc\uad00\uc801\uc778 \uace0\ucc30\uc744 \uc801\uc740 \uae00\uc785\ub2c8\ub2e4. \ub098\uc624\uc9c0 \uc54a\uc740 \uae30\ub2a5\ub4e4\uacfc \ubd88\ud3b8\ud55c \ud1b5\ud569\uc5d0 \ub300\ud55c \uc544\uc26c\uc6c0\uacfc <a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8079-8c80-edd09db9fe25\\">TypeScript \uc131\ub2a5 \ucd5c\uc801\ud654</a>\uc640 \ud0c0\uc785 \ucd94\ub860\uc744 \ud1b5\ud55c full typesafe\uc5d0 \ub300\ud55c \ubd88\ub9cc\uc774 \uc8fc\ub97c \uc774\ub8e8\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-801d-bcb8-f77c4b96b611\\" id=\\"1aae548d-8a8e-801d-bcb8-f77c4b96b611\\"><code>WeakMap</code>\ub97c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c</h2><a href=\\"https://jlongster.com/subverting-control-weak-refs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jlongster.com/subverting-control-weak-refs</a><p data-notion-block-id=\\"1aae548d-8a8e-8036-9ae4-d1b58225dc75\\"><code>WeakMap</code>\uc740 <a href=\\"https://jotai.org/docs/guides/core-internals\\">jotai\uc5d0\uc11c \uc0ac\uc6a9\ud558\uace0 \uc788\uc744 \uc815\ub3c4</a>\ub85c \uc77c\ubc18\uc801\uc774\uc9c0\ub9cc, \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc5d0\uc11c \ubc14\ub85c \uc0ac\uc6a9\ud560\ub9cc\ud07c \uce5c\uc219\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c\ud558\ub294\uc9c0 \uc608\uc2dc\uc640 \ud568\uaed8 \uce5c\uc808\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-809d-98dc-c0c6b61aa18b\\" id=\\"1aae548d-8a8e-809d-98dc-c0c6b61aa18b\\">JS \uac1c\ubc1c\uc790\uc640 Rust \ud50c\ub7ec\uadf8\uc778</h2><a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-11/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-11/</a><p data-notion-block-id=\\"1aae548d-8a8e-80e2-979b-ffb8c5fb5406\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/193e548d-8a8e-80e3-8106-c7aeec326304#195e548d-8a8e-80ab-af5b-caa2eef726d5\\">Rust\uc5d0\uc11c TypeScript\ub85c</a> \ubc14\uafbc Prisma\uc758 \uacb0\uc815\ucc98\ub7fc, Rust \uae30\ubc18 \ucf54\uc5b4 \ub85c\uc9c1\uc5d0 \ucee4\uc2a4\ud140 \ub85c\uc9c1\uc744 \ub123\uae30\uc5d0\ub294 \uc5ec\ub7ec \uc560\ub85c\uc0ac\ud56d\uc774 \uc788\uae30\uc5d0 Rust\ub97c JS \uae30\ubc18 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uae30\uc5d0 \uc5b4\ub824\uc6c0\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 Rust \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c JS \ud50c\ub7ec\uadf8\uc778\uc744 \uc131\ub2a5 \uc800\ud558 \uc5c6\uc774 \uc2e4\ud589\ud558\ub294 \ud574\uacb0\ucc45\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80cf-92c9-f827cdc4c8b1\\" id=\\"1aae548d-8a8e-80cf-92c9-f827cdc4c8b1\\">\ud568\uc218\ud615 \ud328\ub7ec\ub2e4\uc784\uc740 React\uc758 \uc5b4\ub514\uc5d0 \uc788\ub294\uac00</h2><a href=\\"https://www.56kode.com/posts/level-up-react-functional-programming-in-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.56kode.com/posts/level-up-react-functional-programming-in-react/</a><p data-notion-block-id=\\"1ade548d-8a8e-80f6-9117-ee081f89a8d1\\">React\uc5d0\uc11c \uc5ec\ub7ec \ud568\uc218\ud615 \ud328\ub7ec\ub2e4\uc784\uc774 \uc801\uc6a9\ub418\uc5c8\ub2e4\uace0 \ud558\ub294\ub370, \uc65c \uc801\uc6a9\ud588\uace0, \uc5b4\ub514\uc5d0 \uc801\uc6a9\ub418\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774 \uae00\uc744 \ud1b5\ud574 \ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d\uc5d0 \uad00\uc2ec\uc774 \uc0dd\uacbc\ub2e4\uba74, <a href=\\"https://ones-to-watch.ethansup.net/news/post/b251305b-8c2f-4fcc-a159-c495533e1ac4#5bccdfa5-5519-4a47-85b6-15e55ddef4bc\\">\ud568\uc218\ud615 \ud504\ub85c\uadf8\ub798\ubc0d \uc785\ubb38\ud558\uae30</a>\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"1ade548d-8a8e-80f9-af85-e16f77252e47\\" id=\\"1ade548d-8a8e-80f9-af85-e16f77252e47\\">\uae30\ubc1c\ud55c \uc560\ub2c8\uba54\uc774\uc158 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://www.joshwcomeau.com/blog/whimsical-animations/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/blog/whimsical-animations/</a><p data-notion-block-id=\\"1ade548d-8a8e-8051-85fe-c79e9cff452e\\">\uae00\uc4f4\uc774\uac00 \uc5ec\ub7ec\uac00\uc9c0 \uae30\ubc1c\ud55c \uc560\ub2c8\uba54\uc774\uc158\uc744 \uad6c\ud604\ud558\uba74\uc11c \uc0ac\uc6a9\ud55c \uc5ec\ub7ec\uac00\uc9c0 CSS \uc18d\uc131, svg \ubc29\uc2dd, \uc218\ud559\uc801 \uac1c\ub150\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80fd-872a-e0ccfd155f66\\" id=\\"1aae548d-8a8e-80fd-872a-e0ccfd155f66\\">INP\ub97c \ud5a5\uc0c1\ud558\ub294 \uc218\ub9ce\uc740 \ubc29\ubc95\ub4e4</h2><a href=\\"https://medium.com/preply-engineering/how-preply-improved-inp-on-a-next-js-application-without-react-server-components-and-app-router-491713149875\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/preply-engineering/how-preply-improved-inp-on-a-next-js-application-without-react-server-components-and-app-router-491713149875</a><p data-notion-block-id=\\"1aae548d-8a8e-80cd-b55f-e470bf2c57ba\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/156e548d-8a8e-8024-aec1-fd27c897c295#156e548d-8a8e-80df-95e3-c34f92e4fc7f\\">React\uc5d0\uc11c INP \uac1c\uc120\ud558\uae30</a> \uae00\uc758 \ubc29\ubc95 \uc774\uc678\uc5d0\ub3c4 INP\ub97c \uac1c\uc120\ud558\ub294 \ubc29\ubc95\uc740 \ub9e4\uc6b0 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c INP\ub97c \uce21\uc815\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5bb\uac8c \uac1c\uc120\ud588\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-80bb-a2e0-e8b02e97b67f\\" id=\\"1aae548d-8a8e-80bb-a2e0-e8b02e97b67f\\">WebAuthn \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\uc8e0</h2><a href=\\"https://www.heal.dev/docs/blog/testing-webauthn\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.heal.dev/docs/blog/testing-webauthn</a><p data-notion-block-id=\\"1ade548d-8a8e-809c-9bd9-ef9bd6063fd2\\">WebAuthn\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 WebAuthn\uc744 \uad6c\ud604\ud588\uc744 \ub54c \ud14c\uc2a4\ud2b8\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1aae548d-8a8e-8044-96cd-e2fa916eb651\\" id=\\"1aae548d-8a8e-8044-96cd-e2fa916eb651\\"><code>throw</code> vs <code>return</code></h2><a href=\\"https://sergiodxa.com/articles/throwing-vs-returning-redirects-in-react-router\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://sergiodxa.com/articles/throwing-vs-returning-redirects-in-react-router</a><p data-notion-block-id=\\"1aae548d-8a8e-801f-88c2-e660082688c2\\">React Router\uc5d0\uc11c\ub294 <code>throw</code>\ub85c redirect\ud558\ub294 \uac83\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uc774 \uacbd\uc6b0 \uc5b4\ub290 \ub54c <code>throw</code>\ub85c redirect\ub97c \uc368\uc57c\ud558\uace0, <code>return</code>\uc73c\ub85c redirect\ud558\ub294 \uac83\uc744 \uc368\uc57c\ud558\ub294\uc9c0 \uace0\ubbfc\ud574\ubcf4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"1ade548d-8a8e-80d4-96e4-fa676857ebcb\\"></p>"}')}}]);